                    <label for="P">Potência (W)</label>
                    <input type="number" id="P" placeholder="Ex: 144" step="any" required>
                </div>
                <button class="btn btn-success w-100 mt-2" onclick="calculatePower()">Calcular V ou I</button>
                <div class="result-box">
                    <h4>Resultado:</h4>
                    <p id="powerResult"></p>
                </div>
            </div>
        </div>
    </section>

    <!-- Grupo 2: Outros Cálculos Importantes -->
    <section class="calc-section">
        <h2 class="group-title">🔌 Outros Conceitos Essenciais</h2>

        <div class="row g-4">
            <!-- Corrente (I = V/R) -->
            <div class="col-md-6">
                <h3>Corrente Elétrica (I = V / R)</h3>
                <div class="form-group">
                    <label for="V2">Tensão (V)</label>
                    <input type="number" id="V2" placeholder="Ex: 12" step="any" required>
