                <div class="result-box">
                    <h4>Resultado:</h4>
                    <p id="currentResult"></p>
                </div>
            </div>

            <!-- Resistividade (ρ = R * A / L) - simplificado para comprimento e área -->
            <div class="col-md-6">
                <h3>Resistividade (ρ = R * L / A)</h3>
                <div class="form-group">
