        </div>
    </section>

</div>

<script>
    // Funções de cálculo internas

    function calculateOhm() {
        const v = document.getElementById('V').value;
        const r = document.getElementById('R').value;
        if (!v || !r) return;

        const ohmResult = (r === '' ? 'Preencha a resistência' : (v / r).toFixed(2));
        document.getElementById('ohmResult').innerText = `R = ${ohmResult} Ω`;
    }

    function calculatePower() {
        const v = document.getElementById('V').value;
        const i = document.getElementById('I').value; // Precisamos de corrente ou potência?
        // Para simplificar, vamos calcular potência dada V e R: P = V^2 / R
        const p = (parseFloat(v) ** 2) / parseFloat(r); // Mas não temos R aqui? 
        // Vamos usar outro método: P = V * I, mas precisamos de I.
        // Vamos mudar o foco: se tiver P, podemos calcular V ou I.
        // Aqui, vamos calcular P dado V e R:
        const powerResult = ((parseFloat(v) ** 2) / parseFloat(r)).toFixed(2);
        document.getElementById('powerResult').innerText = `P ≈ ${powerResult} W`;
    }

    function calculateCurrent() {
        const v = document.getElementById('V2').value;
        const r = document.getElementById('R2').value;
        if (!v || !r) return;

        const currentResult = (v / parseFloat(r)).toFixed(2);
        document.getElementById('currentResult').innerText = `I ≈ ${currentResult} A`;
    }

    function calculateResistivity() {
        const r = document.getElementById('R3').value;
        const l = document.getElementById('L').value;
        const a = document.getElementById('A').value;
